/** Decode saved membership only. Integration must still check actual support and shared exclusions. */
export async function decodeVerifiedPlantingRoots(){
 const compressed=Uint8Array.from(atob(encoded),c=>c.charCodeAt(0));
 const buffer=await new Response(new Blob([compressed]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();
 if(buffer.byteLength!==H_EARTH_VERIFIED_PLANTING_PACKET.recordCount*8)throw Error('VERIFIED_PLANTING_RECORD_LENGTH');
 const view=new DataView(buffer),roots=new Array(H_EARTH_VERIFIED_PLANTING_PACKET.recordCount),f=Math.fround;
 for(let i=0;i<roots.length;i++){
  const p=i*8,ix=view.getInt16(p,true),iz=view.getInt16(p+2,true),y=view.getFloat32(p+4,true);
  if(!Number.isFinite(y))throw Error('VERIFIED_PLANTING_NONFINITE_HEIGHT');
  roots[i]={x:f((ix+.5+(habitatHash(ix,iz,80)/4294967296-.5)*.76)*.14),y,
   z:f((iz+.5+(habitatHash(ix,iz,81)/4294967296-.5)*.76)*.14),
   angle:f(habitatHash(ix+8000000,iz+8000000,3)/4294967296*Math.PI*2),
   seed:habitatHash(ix+8000000,iz+8000000,4),region:'RAVINE'};
 }
 return roots;
}
